insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 1, 'What is the reason a casing string is cemented, above every other?', '["Support, so the wellhead does not carry the whole string.", "Zonal isolation: keeping the fluid in one formation out of every other formation and out of the annulus.", "Corrosion protection, since formation water on the outside of the steel would otherwise shorten the life of the well.", "To give the next hole section a competent foundation to be drilled out of and a shoe to leak-off test against."]'::jsonb, 1, 'The other three are real and none of them is why the job exists.'),
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 2, 'What does a failed cement job usually look like?', '["A loss of returns while the cement is being pumped.", "A pressure test that fails, which is why the test is performed before the next hole section is drilled ahead.", "Nothing during the job, and a problem decades later, which is what makes the subject difficult to learn from.", "Nothing at all during the job, and sustained casing pressure or unexpected water years later."]'::jsonb, 3, 'The job is done in a few hours and judged decades later.'),
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 3, 'Which of these does this engine deliberately not compute?', '["Cement chemistry: thickening time, compressive strength, free water, fluid loss and gas migration.", "The annular capacity of the open hole section.", "The equivalent circulating density at the previous casing shoe, which is a placement result rather than a volume one.", "The standoff of the casing in the hole, which is left to a separate centralization package outside this suite."]'::jsonb, 0, 'It places a fluid of a stated density and rheology in a stated geometry, and what that fluid becomes is a laboratory question.'),
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 4, 'The four requirements of a cement job conflict. Name one such conflict.', '["Ordering more slurry makes the job take longer.", "Using a spacer keeps the mud and the cement apart and reduces the total volume of cement that has to be purchased.", "Raising the top of cement improves isolation and worsens the circulating density at the weakest shoe.", "A deeper float collar increases the shoe track and reduces the displacement volume by the same amount at once."]'::jsonb, 2, 'Pumping faster and pumping slower is the other one, and it is what the Professional tier is built on.'),
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 5, 'Where is the float collar, and why is there one at all?', '["At the shoe, as a rounded nose that stops the string hanging up.", "One or two joints above the shoe, so that two one-way valves rather than one stand between the annulus and the casing.", "At the top of cement, so that the plug lands there and the cement above it is not displaced out into the annulus.", "At the previous casing shoe, which is where the lead and tail split is normally placed on a two-slurry job."]'::jsonb, 1, 'On both of this course''s wells it is 40 m above the shoe.'),
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 6, 'What is the shoe track for?', '["Keeping the most contaminated cement, which is the last out of the casing, inside the pipe rather than at the shoe.", "Providing extra weight at the bottom of the string.", "Giving the top plug somewhere to land, which is what ends the job and produces the pressure spike the crew watches for.", "Holding a reserve of cement in case the annulus turns out to take more than the volume sheet predicted for it."]'::jsonb, 0, 'The shoe is the single most important place for the cement to be good, because the next leak-off test is performed there.'),
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 7, 'The displacement volume is measured to which depth?', '["The shoe, since that is the bottom of the casing.", "The top of cement, because the displacement only has to push the cement as far as its target rather than to the bottom.", "The float collar rather than the shoe, so that the shoe track cement stays inside the casing where it was meant to.", "The float collar, because that is where the top plug lands and the volume between it and the shoe is the shoe track."]'::jsonb, 3, 'Displace to the shoe and you have pushed the shoe track cement out into the annulus.'),
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 8, 'What is the spacer between the mud and the cement for?', '["Adding volume so the cement reaches the target top.", "Cleaning the inside of the casing ahead of the bottom plug, which is what the plug''s wiping fins would otherwise have to do.", "Keeping two fluids apart that flocculate on contact, water-wetting the surfaces, and stepping the density hierarchy.", "Providing a lighter column so the equivalent circulating density at the shoe above stays under the fracture gradient."]'::jsonb, 2, 'On this course''s jobs it is 4 cubic metres at 1500 kg/m3, between a mud at 1440 and a lead at 1560.'),
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 9, 'Which of these does the engine refuse rather than approximate?', '["An open hole excess above 50 percent.", "A liner job, which it names as a later phase because the hanger depth changes the whole flow path.", "A top of cement above the previous casing shoe, since bringing cement inside the previous string is a separate calculation.", "A pump rate high enough that the equivalent circulating density at the previous shoe exceeds the fracture gradient there."]'::jsonb, 1, 'It says which phase the input belongs to rather than treating a liner as a short full string.'),
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 10, 'What does the engine''s plug flow assumption cost?', '["The whole subject of intermixing, which is what a spacer exists to control and what contaminates a slurry.", "Exactness, since the fronts have to be solved for numerically.", "The ability to compute the annular capacity, since a mixed fluid has no single density to compute a hydrostatic head from.", "Reproducibility, because the interface positions depend on the order the segments happened to be summed in."]'::jsonb, 0, 'It buys exactness and reproducibility and speed, which is what makes the rate sweeps in the next tier affordable.'),
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 11, 'What does every result this engine returns carry?', '["A confidence interval on the reported volumes.", "A checksum over the inputs, so that a result cannot be presented alongside a geometry it was not actually computed from.", "A version string, so a saved answer can be traced to the code that produced it.", "A timestamp and the name of the user who ran it, which is what makes a saved cement programme auditable after the fact."]'::jsonb, 2, 'A placement result and a standoff profile both carry it.'),
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 12, 'Casing movement during the job is left out of this engine. Why does that matter?', '["Because it changes the displacement volume.", "Because a moving casing has a different annular friction, which shifts the equivalent circulating density at the shoe above.", "Because it is one of the two biggest levers a cementing engineer has, and the model can only quantify the other one.", "Because rotating or reciprocating the casing is the most effective mud removal technique there is."]'::jsonb, 3, 'An answer from this engine is a lower bound on what a well-executed job achieves.'),
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 13, 'How many stages does this engine model?', '["Two, a lead stage and a tail stage.", "One. It cements a full string from surface in a single stage, and a stage collar is not represented.", "As many as the fluid list has entries, since each pumped fluid is treated as a separate stage of the placement calculation.", "One per hole section, so a string that passes through two sections is placed as two independent stage calculations."]'::jsonb, 1, 'A staged job is one of the four remedies for a closed rate window, and it is outside this course.'),
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 14, 'What does the engine do about the transient rate during a free fall?', '["Reports the deficit and refuses to compute the rate, saying so in the warning text.", "Computes it from the friction of the falling fluid.", "Clamps the rate to the pump rate, which is conservative because the real fall is always faster than the pumps deliver.", "Halts the simulation at the first free-fall step, since none of the numbers after it would be meaningful anyway."]'::jsonb, 0, 'It can say when it happens and by how much the balance is negative, and not how fast.'),
  ('cementing', 'beginner', 'module', 'm01-what-a-primary-cement-job-is', 15, 'What is the honest summary of what a volume sheet is good for?', '["Predicting whether the job will isolate the reservoir.", "Establishing the fracture gradient at the previous shoe, which is what limits how much cement can be placed at all.", "Ordering: it converts a geometry into a purchase order and a schedule, reproducibly.", "Confirming that the casing will be centred well enough for the cement to displace the mud all the way round it."]'::jsonb, 2, 'Two engineers working from the same geometry get the same sheet, and that is all it is.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 1, 'How many diameters does the volume calculation need at each depth?', '["Two, the casing outside diameter and the bore.", "Three: the casing outside and inside, and the bore around it, and only the last one changes with depth.", "Four, since the open hole needs both the bit size and the effective bore that the excess factor produces from it.", "One, the annular clearance, since every capacity in the calculation can be derived from the clearance alone."]'::jsonb, 1, 'The casing is one size for the whole string in this engine, so only the bore around it varies.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 2, 'What does this course''s job cement, and inside what?', '["A 7 inch production string, inside 9-5/8 inch casing near surface and an 8-1/2 inch open hole below.", "A 9-5/8 inch intermediate string inside 13-3/8 inch casing.", "A 7 inch liner hung off the previous shoe, which is why the hanger depth is a required input to the volume routine.", "A 20 inch surface string in a 26 inch hole, which is the case where the open hole excess assumption matters most."]'::jsonb, 0, 'Previous shoe at 1400 m on the slant well and 1200 on the horizontal one.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 3, 'At the BIT SIZE, which annulus is narrower on this well?', '["The cased section, at 0.013356688045922537 square metres.", "Neither, because the previous casing bore and the bit size are chosen to give the same annular area around the string.", "The open hole one, at 0.011780948889016823 against the cased section''s 0.013356688045922537 square metres.", "The open hole, because an 8-1/2 inch bit drills a smaller hole than the 9-5/8 inch casing it is drilled through."]'::jsonb, 3, 'Once the excess is applied the ordering reverses, and that is a whole lesson in the next module.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 4, 'What is an annulus capacity row?', '["One survey station and the inclination there.", "One fluid in the annulus at the end of the job, with the depths it spans and the density it was pumped at.", "One interval of constant bore, carrying a capacity, an effective bore and whether it is open hole.", "One hole section from the well plan, copied across unchanged so that the volume calculation can read it directly."]'::jsonb, 2, 'The rows run from surface to the casing shoe and carry no inclination, no formation and no pressure.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 5, 'Where does the engine cut the annulus into rows?', '["At every survey station in the trajectory.", "At zero, at the casing shoe, and at every hole section boundary above the shoe.", "At the top of cement and the lead and tail split, since those are the depths the volume calculation needs endpoints at.", "Wherever the annular capacity changes by more than one percent, which is a tolerance the caller can set."]'::jsonb, 1, 'The top of cement and the split are handled by taking the overlap with each row rather than by cutting one.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 6, 'How does the engine compute a volume between two depths?', '["By summing, over the rows, the capacity times the overlap of the requested interval with that row.", "By multiplying the average capacity by the interval length.", "By integrating the capacity along the trajectory, which requires the survey because the rows are in measured depth.", "By splitting the rows at the two endpoints and then adding the volumes of the rows that fall entirely inside."]'::jsonb, 0, 'That three-line function is the whole of the volume calculation.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 7, 'The inside capacity on this casing is 0.01937743444976952 square metres. How does it compare with the cased annulus?', '["About half, since the annulus is the larger of the two.", "Almost identical, which is a coincidence of the 7 inch casing sitting inside a 9-5/8 inch bore at these two weights.", "About 45 percent larger, which is why the displacement dominates the total pumped volume.", "About four times larger, which is why the shoe track is the largest single volume on the whole sheet."]'::jsonb, 2, 'The slant well pumps 57.357205971317775 cubic metres of displacement against 25.123380942966243 of slurry.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 8, 'The engine skips a row whose two cut depths are within a nanometre. Why?', '["Because a row shorter than a nanometre is a data error.", "Because a zero-length row would contribute nothing and would divide by zero in the volume-to-depth mapping.", "Because the coverage check would fail on it, since no hole section can be found for a midpoint that is not well defined.", "Because two cuts that close together mean two hole sections overlap, which is an inconsistency the caller should fix."]'::jsonb, 1, 'The mapping divides the volume by the capacity to recover a depth, and a zero-length row has zero volume.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 9, 'The coverage check finds the hole section covering what?', '["The top of each row, which is where the cut was made.", "Every survey station inside the row, so that a section that covers only part of the row is detected and refused.", "The midpoint of the row, and if no section covers it the engine throws and names the interval it could not cover.", "The MIDPOINT of each row, and it throws with the interval named if there is no such section."]'::jsonb, 3, 'A hole description with a gap in it is a data error, and a volume computed over a gap would silently be too small.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 10, 'What does the fit check refuse?', '["A casing outside diameter that is not strictly smaller than the bore, naming the interval and whether it was cased or open.", "A casing inside diameter larger than the outside one.", "A top of cement below the casing shoe, which is a squeeze job rather than a primary cement job and is out of scope here.", "An annular clearance below ten millimetres, which is the smallest a bow spring centralizer can be run in."]'::jsonb, 0, 'It catches a casing size and a bit size that were never meant to go together.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 11, 'Why does the engine refuse a liner job by name rather than treating it as a short full string?', '["Because a liner has no shoe track.", "Because the annulus rows would have to start at the hanger rather than at surface, which the row cutting cannot represent.", "Because a hanger above zero changes the flow path, the displacement volume and the U-tube completely.", "Because a liner is run on a work string whose inside capacity differs from the liner''s, so the displacement would be wrong."]'::jsonb, 2, 'Every refusal in the module could have been given a plausible answer, and every plausible answer would be undetectable.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 12, 'Which of these is an INSIDE depth rather than an annulus one?', '["The top of cement, which is an annular target.", "The float collar, which is why the inside needs no capacity rows at all.", "The lead and tail split, which divides the annular slurry between the two cements at a chosen measured depth.", "The previous casing shoe, which is where the annulus changes from steel to rock and the rows are cut."]'::jsonb, 1, 'The inside has one capacity for the whole string, because the string is one size.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 13, 'What limits how far down the annulus rows run?', '["The casing shoe, because nothing below it is being cemented by this job.", "The total depth of the hole as drilled.", "The deepest survey station, since the minimum-curvature interpolation cannot produce a true vertical depth beyond it.", "The top of cement, since the annulus above it holds no cement and therefore contributes no volume to the sheet."]'::jsonb, 0, 'There is usually hole below the shoe, and it is not part of the job.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 14, 'What would happen to the volume sheet if the casing were tapered?', '["The engine would refuse the input by name.", "The annulus rows would be cut at each change of casing weight, and the inside would be handled the same way.", "Nothing would refuse the input, which makes it a real limitation that is easy to miss on a string with more than one weight.", "The shoe track and the displacement would be computed on whichever single inside diameter was supplied."]'::jsonb, 3, 'The engine takes one inside diameter and one outside diameter for the whole string.'),
  ('cementing', 'beginner', 'module', 'm02-the-geometry', 15, 'Where does the inclination of the well enter the volume calculation?', '["In the annular capacity, through the true vertical depth.", "Nowhere. It enters the hydrostatic head and the centralization, and the volume sheet reads only measured depths.", "In the annulus row cutting, since a building section is split more finely than a tangent one to keep the capacity accurate.", "In the displacement volume, which is measured along the hole and therefore longer on a deviated well than a vertical one."]'::jsonb, 1, 'It is why the slant and horizontal wells have identical slurry volumes.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 1, 'Why is an open hole bigger than the bit that drilled it?', '["Because the bit gauge wears as the section is drilled.", "Washout from circulating mud, breakout where the rock fails in shear, and dissolution in a soluble section.", "Because the minimum-curvature trajectory understates the hole length, so the same volume is spread over fewer metres.", "Because the mud filter cake on the wall is compressible and collapses inward once the casing displaces the mud."]'::jsonb, 1, 'All three, and none of them is measured unless a caliper is run.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 2, 'Which calculation in this suite is most sensitive to the hole being bigger than the bit?', '["Casing collapse, which depends on the external pressure.", "Torque and drag, since the side force on the string depends on the clearance between the pipe and the wall of the hole.", "Cement volume, since a hole ten percent bigger in area takes ten percent more cement and the shortfall shows up at the top.", "Cement volume, because the cement volume IS the annular capacity."]'::jsonb, 3, 'Every other calculation in the suite is happy with the bit size.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 3, 'Which way is the excess guess deliberately biased, and why?', '["High, because guessing low leaves an uncemented interval and guessing high mostly costs money.", "Low, because excess cement is expensive.", "Neither, since the two errors are symmetric and the best estimate from offset wells is what should be used.", "High, because a heavier annular column reduces the risk of the formation flowing while the cement is setting."]'::jsonb, 0, 'The two errors are not symmetric, which is why the industry uses figures known to be generous.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 4, 'Where in the code is the excess factor applied?', '["In the job volume routine, after the rows are built.", "In the placement simulation, where the annular velocity has to be recomputed on the inflated capacity for the friction term.", "In the annulus row builder, multiplying the capacity of open hole rows only.", "In the annulus row builder, applied to every row, since a cased annulus is also larger than nominal once the casing wears."]'::jsonb, 2, 'Cased rows are untouched, because the inside diameter of a piece of steel is a measurement rather than a guess.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 5, 'What is the relationship between the excess and the slurry volume?', '["Quadratic, because the excess is applied to the diameter.", "Exactly linear, with a positive intercept that is the part of the job not in open hole.", "Linear in the open hole part and quadratic in the cased part, which is why the total curves slightly at high excess figures.", "Approximately linear, with a small nonlinearity from the effective bore feeding back into the friction calculation."]'::jsonb, 1, 'The excess multiplies a capacity, the capacity multiplies a length, and the rest of the job is fixed.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 6, 'The effective bore is back-solved from the inflated capacity. Why not just inflate the diameter?', '["Because a ten percent bigger diameter is a twenty one percent bigger area, and the excess is quoted as a volume excess.", "Because the diameter is not used anywhere downstream.", "Because the back-solve is cheaper than a square root, and the placement needs the capacity rather than the diameter.", "Because the API convention defines the excess against the diameter rather than the area, so a conversion is needed either way."]'::jsonb, 0, 'Getting that backwards is a real and common error, and the engine documents its convention where it applies it.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 7, 'At 15 percent excess the open hole effective bore is 0.22104932820526735 m. What does that reverse?', '["It makes the open hole annulus narrower than nominal.", "It makes the annular velocity in the open hole higher than in the cased section, which improves mud removal down there.", "The washed-out open hole annulus becomes wider than the cased one above it, which it was not at the bit size of 0.2159 m.", "The open hole annulus becomes WIDER than the cased annulus it hangs from, which at the bit size it was not."]'::jsonb, 3, 'It matters for the annular velocity, which is lowest where the annulus is widest.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 8, 'Which volumes does the excess NOT touch?', '["Only the displacement, since the shoe track is in open hole.", "None of them, because the excess is applied at the annulus row level and every volume on the sheet reads those rows.", "The displacement and the shoe track, both inside the casing, and the cased part of the annular slurry.", "The lead volume, since the lead sits inside the previous casing where the bore is a measurement rather than an estimate."]'::jsonb, 2, 'On this well about 89 percent of the annular slurry is exposed to the assumption.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 9, 'Fifteen percentage points of excess is worth about how many sacks on this job?', '["About 20 sacks, rising as the excess rises.", "About 74 sacks, and the same 74 whether you go from 0 to 15 or from 15 to 30.", "It depends on the top of cement, since the excess applies to the whole annular slurry rather than to the open hole part.", "About 150 sacks, which is a quarter of the total and is what makes the excess the largest single cost on the job."]'::jsonb, 1, 'The relationship is linear, so equal steps in excess cost equal numbers of sacks.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 10, 'Getting the excess wrong LOW by 15 percentage points on this job costs what?', '["About 212 m of uncemented annulus at the top, from 2.8274277333640363 cubic metres of missing slurry.", "About 74 sacks of wasted cement.", "Nothing, because the placement simulation would have warned that the achieved top of cement missed its target by 30 m.", "About eight minutes of job time, since the total pumped volume falls and the pump rate is unchanged throughout."]'::jsonb, 0, 'Two hundred metres is why the industry biases the guess upward.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 11, 'Besides money and time, what does a generous excess cost?', '["Nothing at all, which is why generosity is free.", "Job quality, since a larger volume of slurry has to be mixed in the same time and the mix density becomes less consistent.", "Margin against the fracture gradient, because a taller heavier annular column raises the circulating density.", "Accuracy in the achieved top of cement, since the placement simulation is run at a different excess from the volume sheet."]'::jsonb, 2, 'A generous excess is not free: it moves the job toward the fracture limit.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 12, 'Walking the inputs to a volume sheet, how many are guesses?', '["Three: the excess, the yield and the top of cement.", "Two, the excess and the slurry yield, since the yield is measured on a laboratory blend rather than on the field mix.", "One, the open hole excess, and every other input to the sheet is either a measurement or a deliberate design choice.", "One. Every other input is a published table, a joint tally, a bit stamp, a laboratory test or a design decision."]'::jsonb, 3, 'Every other uncertainty is in the third or fourth significant figure and this one is in the first.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 13, 'The engine reports 25.123380942966243 cubic metres of slurry. What is the honest statement?', '["25.123 cubic metres, to the precision quoted.", "Somewhere between about 23 and 28, and the sheet says 25.123 because a purchase order needs a number.", "25.123 plus or minus the rounding on the casing dimensions, which is the largest uncertainty on the whole calculation.", "It cannot be stated at all without a caliper log, so a volume sheet without one is not a usable document."]'::jsonb, 1, 'The arithmetic on the inputs given is correct to every digit and the precision of the answer is a fiction.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 14, 'What are the four things to do about the excess?', '["Report it next to the answer, sweep it, bias it deliberately, and get a caliper where the section matters.", "Use the field template value and move on.", "Compute it from the drilling time, the mud type and the formation, which is the correlation offset operators use for it.", "Apply it to the diameter rather than the area, and then report the resulting volume as a range rather than a point."]'::jsonb, 0, 'A slurry volume with no excess figure attached is not a result.'),
  ('cementing', 'beginner', 'module', 'm03-open-hole-excess', 15, 'What is the general habit this module teaches?', '["Always round the reported volume to three digits.", "Never report a volume without also reporting the annular capacity and the two depths the volume was integrated between.", "Any answer whose precision exceeds the precision of its worst input is quoting arithmetic rather than engineering.", "Compute every volume twice, once at the design excess and once at zero, and quote the two as a lower and upper bound."]'::jsonb, 2, 'It is the same habit the Casing and Tubing course taught as computing the gap.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 1, 'Which input to the volume sheet is a design decision rather than a measurement or a guess?', '["The open hole excess, chosen from offset well data.", "The top of cement, which is chosen by an engineer who can defend it against a regulation and a lap requirement.", "The slurry yield, which is selected from a service company catalogue rather than measured on the blend actually used.", "The float collar depth, which the engineer chooses as a compromise between shoe track quality and drill-out time."]'::jsonb, 1, 'It is the only one of the three kinds of number on the sheet that somebody actually decides.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 2, 'Both of this course''s wells put the top of cement 200 m above the previous shoe. What is that?', '["The lap: cementing inside the previous casing so the overlap between the two strings is cemented.", "A regulatory minimum above the reservoir.", "The distance needed for the lead slurry volume to reach a full annulus row, which is what the split calculation requires.", "A rule of thumb from the fracture gradient, since 200 m of extra column is what the shoe above can just tolerate."]'::jsonb, 0, 'It is the design choice, and it is why the lead volume on both wells is exactly 200 m of cased annulus.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 3, 'Where does the top of cement enter the arithmetic?', '["In the displacement volume, as a lower limit.", "In the shoe track, since the shoe track is the part of the cement column that never leaves the casing at all.", "Once, as the shallow endpoint of the volume between it and the shoe, and nothing else about it matters to the sheet.", "Once, as the upper endpoint of the annular integral, and nowhere else."]'::jsonb, 3, 'The engine refuses a negative one and one below the shoe, and nothing else.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 4, 'The slant well''s annular slurry is 24.34828356497546 cubic metres in how many pieces?', '["One, since the annulus has a single capacity.", "Three, since the shoe track is part of the annular slurry and is computed on the inside capacity rather than the annular one.", "Two: 2.6713376091845076 in the cased annulus and 21.676945955790952 in the open hole.", "Two, of which the cased piece is the larger because the cased annulus has the greater capacity per metre."]'::jsonb, 2, 'The open hole piece is about 89 percent of it, which is the part the excess touches.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 5, 'The two wells have identical annular slurry volumes. Why?', '["Because the volume is normalised by the total depth.", "Because both have 200 m of cased annulus above the shoe and 1600 m of open hole, in the same two sizes.", "Because the excess factor is chosen per well so that the ordered volumes come out the same for the same slurry blend.", "Because the annular capacity is the same on both, and the annular slurry depends on the capacity rather than the length."]'::jsonb, 1, 'Every interval is the same length; only the absolute depths differ.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 6, 'The shoe track on both wells is 0.7750973779907808 cubic metres. What is that made of?', '["Forty metres of casing bore at 0.01937743444976952 square metres.", "Forty metres of annulus at the open hole capacity.", "The difference between the displacement volume and the total inside volume of the casing, which the engine computes directly.", "The volume between the float collar and the top of cement, which is the part of the slurry that stays inside the pipe."]'::jsonb, 0, 'The float collar is 40 m above the shoe on both wells.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 7, 'Why is the shoe track only 40 m and not 200?', '["Because the plug cannot travel further than 40 m.", "Because the shoe track volume is subtracted from the displacement, and a longer one would leave the plug short of the collar.", "Because every metre of it is hard cement somebody has to drill out at the start of the next section.", "Because the API convention sets the shoe track at two joints, and a longer one would not be covered by the standard."]'::jsonb, 2, 'It is a trade between keeping the contaminated tail inside and the drill-out that follows.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 8, 'What does the lead and tail split do to the total slurry volume?', '["It increases it, because two slurries need more spacer.", "Nothing. Lead plus tail is the slurry volume by construction, whatever depth the split is at.", "It reduces it, because the lead is extended and therefore yields more slurry per sack of dry cement than the tail does.", "It depends on the split depth, since a deeper split puts more of the slurry into the higher-capacity open hole annulus."]'::jsonb, 1, 'Moving the split moves cement from one column of the sheet to the other and changes no total.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 9, 'Why is the lead and tail split usually put at the previous casing shoe?', '["Because the lead slurry is cheaper per cubic metre.", "Because the split has to fall on an annulus row boundary, and the previous shoe is the only one the engine cuts a row at.", "Because it is the deepest point still protected by the casing above, so the strong cement goes where the hole is open.", "Because that is where the annulus changes from steel to rock, so the heavy tail covers all of the open hole."]'::jsonb, 3, 'It is a geometric reason rather than an economic one.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 10, 'The displacement volume on the slant well is 57.357205971317775 cubic metres. Against what?', '["A slurry volume of 25.123380942966243, so more than twice as much fluid is pumped to push the cement as there is cement.", "A slurry volume of 42.83, so they are comparable.", "A total pumped volume of 57.357205971317775, since the displacement is by definition everything pumped behind the top plug.", "A shoe track of 0.7750973779907808, which is the only other inside volume and is therefore what it should be compared with."]'::jsonb, 0, 'The displacement dominates the job and it dominates the job time with it.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 11, 'The two wells'' displacement volumes differ by 3.875486889953905 cubic metres. What is that?', '["The difference in their annular slurry volumes.", "The difference in their true vertical depths at the shoe, converted through the casing bore capacity of the string.", "Two hundred metres of casing bore, which is the difference between their float collar depths.", "Two hundred metres of annulus, which is the difference between the two previous casing shoe depths on the two wells."]'::jsonb, 2, 'It is the first volume in the whole sheet that distinguishes the two wells.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 12, 'Why is the displacement measured to the float collar rather than to the shoe?', '["Because the shoe track cement is not part of the barrier.", "Because the top plug lands on the float collar, and that landing is what ends the job.", "Because the shoe is a one-way valve and the volume below it cannot be displaced without opening the valve the wrong way.", "Because the displacement fluid is lighter than the cement, and displacing past the collar would leave it below the cement."]'::jsonb, 1, 'Over-displacing pushes shoe track cement into the annulus, which is what the shoe track exists to prevent.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 13, 'What is the one real-time check the field has on the whole volume sheet?', '["The plug bump at the calculated displacement volume, which confirms the inside geometry and the arithmetic.", "The returns volume matching the pumped volume.", "The pump pressure falling in the first third of the job, which confirms that heavy cement is going down inside the casing.", "The surface density of the slurry, measured continuously, which confirms the yield and therefore the sacks ordered."]'::jsonb, 0, 'It confirms the inside geometry and says nothing at all about the annulus.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 14, 'What does the displacement fluid''s density decide?', '["The annular velocity during the displacement phase.", "The achieved top of cement, since a heavier displacement pushes the cement further up the annulus than a lighter one.", "One of the two columns in the float differential, since it is the fluid inside the casing when the pumps stop.", "Half of the float differential, because it is what sits inside the casing at the end of the job."]'::jsonb, 3, 'On this course''s jobs it is the same mud the hole started in, at 1440 kg/m3.'),
  ('cementing', 'beginner', 'module', 'm04-the-volumes', 15, 'A crew under-displaces a cement job. What happens?', '["The top of cement ends up higher than planned.", "The shoe track is pushed out into the annulus, which puts the most contaminated cement at the most important place.", "Cement is left inside the casing above the float collar, and it sets there.", "The plug bumps early and the pressure spike is smaller than the crew were expecting to see on the surface gauge."]'::jsonb, 2, 'Over-displacing is the opposite error and it is the one the shoe track exists to defend against.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 1, 'What is a slurry yield?', '["The compressive strength reached after 24 hours.", "The volume of slurry one sack of dry cement makes once mixed with its water and additives.", "The fraction of the ordered volume that actually reaches the annulus, after the shoe track and the contaminated tail.", "The mass of dry blend per cubic metre of finished slurry, which is what a bulk plant loads the tanks against."]'::jsonb, 1, 'On this course''s jobs it is 0.0382 cubic metres a sack, giving 657.6801293970221 sacks.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 2, 'Why are both the yield and the density needed?', '["The density gives the hydrostatic pressure the column exerts and the yield gives the sacks the purchase order needs.", "Because the engine converts between them internally.", "Because the yield is measured in the laboratory and the density in the field, so the two have to be reconciled before the job.", "Because an extended lead slurry has a lower yield and a lower density, and the two must be quoted together to be meaningful."]'::jsonb, 0, 'An extended lead at 1560 has a much higher yield than a neat tail at 1900, because most of the extra volume is water.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 3, 'What does the engine do if no slurry yield is supplied?', '["Uses 0.0382, the value on this course''s jobs.", "Computes one from the slurry density, using the standard relationship between density and yield for a class G blend.", "Reports no sacks, because a yield is a laboratory measurement on a specific blend and there is no default worth having.", "Reports no sacks at all, rather than assuming a default."]'::jsonb, 3, 'Same discipline as the job time, which is only reported if a pump rate is supplied.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 4, 'The engine divides the whole slurry volume by one yield. When is that wrong?', '["On any job, since the yield varies with temperature.", "On a job with a shoe track, since the shoe track cement is never placed and should be excluded from the sack count entirely.", "On a two-slurry job, because the lead has a higher yield than the tail and the sacks of lead are overstated.", "Never, because the yield is a property of the blend and the engine is given the blend the whole job is pumped with."]'::jsonb, 2, 'On this job the lead is about eleven percent of the slurry so the error is contained, and on a long lead it would not be.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 5, 'The slant well''s job time is 4324.029345714201 seconds. What is that?', '["The slurry volume over the mixing rate.", "The total pumped over the pump rate, which is 86.48058691428402 cubic metres at 0.02 cubic metres a second.", "The displacement volume over the pump rate, since the displacement is the only phase that has to be pumped at a fixed rate.", "The sum of the mixing time and the pumping time, which is what a thickening time comparison actually has to be made against."]'::jsonb, 1, 'About 72 minutes, and two thirds of it is displacement.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 6, 'What is the most important use of the job time, and can this engine make it?', '["Comparison against the slurry''s thickening time, and no, because the engine has no thickening time and no temperature.", "Estimating the rig cost at a day rate.", "Setting the annular velocity, since the velocity is the volume over the time and the time is what the crew actually control.", "Deciding the excess factor, since a longer job means a longer exposure of the open hole and therefore more washout."]'::jsonb, 0, 'That comparison is the single most important use of the number and it happens outside this course.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 7, 'The reported job time is a lower bound. What is missing from it?', '["Nothing, since it is the total volume over the rate.", "The time to run the casing, which is the largest single component of the operation the cement job is a part of.", "The mixing, the rate changes and the stops, which together commonly make a real job half again as long as the calculation.", "Mixing, rate changes, the plug drop and the changeover from cement to displacement."]'::jsonb, 3, 'Real jobs slow down to displace the plugs and slow down again for the bump.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 8, 'Which quantity is identical between the two wells, and which is not?', '["The displacement is identical and the slurry is not.", "Every slurry number is identical and the displacement is not, because the float collars are at different depths.", "The sacks are identical and the slurry volume is not, because the two wells are quoted at different slurry yields.", "The job time is identical, since both wells are pumped at the same rate and their total pumped volumes agree."]'::jsonb, 1, 'The annular slurry, the shoe track, the lead, the tail and the sacks all match to the last digit.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 9, 'What does the volume sheet being a function of lengths and diameters mean in practice?', '["It cannot be computed without a survey.", "It is exact, since lengths and diameters are the two quantities in a well that are known to the highest precision available.", "It cannot tell a horizontal well from a slant one, and it gave both of these the same slurry volume.", "It has to be recomputed whenever the trajectory changes, even if the casing programme and the hole sizes stay the same."]'::jsonb, 2, 'A 1600 m horizontal lateral holds exactly as much cement as 1600 m of vertical hole of the same size.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 10, 'Where does the difference between the two wells reappear?', '["Immediately, in the placement, because pressure depends on vertical height and their shoe TVDs differ by nearly 1300 m.", "In the sacks, once the two yields are applied.", "In the annular velocity, since a horizontal well has a longer annulus and therefore a lower velocity at the same pump rate.", "Nowhere, because the whole of this course reads measured depths and the trajectory never enters any calculation."]'::jsonb, 0, 'Their float differentials at the end of the job differ by a factor of ten.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 11, 'Which of these does a volume sheet NOT hide?', '["Whether the cement will still be pumpable when it arrives.", "Whether the mud on the narrow side of an eccentric annulus will be displaced or left there as a channel down one side.", "Whether the formation at the previous shoe will hold the pressure the cement column and its friction will apply to it.", "How much of each fluid to order, which is the one thing it exists to compute."]'::jsonb, 3, 'It converts a geometry into a purchase order, reproducibly, and that is all it does.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 12, 'Which tier of this course addresses whether the hole will take the cement?', '["The Associate tier, through the excess factor.", "The Professional tier, which computes the equivalent circulating density at the previous shoe through the job.", "The Expert tier, since a channel is what forms when the formation takes fluid and the cement follows it out of the annulus.", "None of them, because the fracture gradient comes from the Geomechanics course and this course never compares against it."]'::jsonb, 1, 'The Expert tier addresses whether the mud gets out of the way, and three of the six omissions are outside the course.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 13, 'What is the one real-time confirmation of the displacement volume?', '["The plug bumping at the calculated volume, which is one of the few live checks on the whole sheet.", "The returns volume matching the pumped volume.", "A temperature log run after the cement sets, which locates the top of cement and therefore confirms the annular volume.", "The surface pressure rising through the last third of the job, which confirms that cement is arriving in the annulus."]'::jsonb, 0, 'A job where the plug does not bump at the calculated volume is a job where the geometry was wrong.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 14, 'Why can two engineers working from the same geometry be relied on to produce the same volume sheet?', '["Because the excess is fixed by the API convention.", "Because the engine version string travels with the answer, so any disagreement can be traced to a difference in the code.", "Because every step is cylinder arithmetic with no judgement in it once the inputs are agreed.", "Because the sheet is generated from the well plan directly, so neither engineer enters any of the numbers by hand at all."]'::jsonb, 2, 'Reproducibility is most of the value of the sheet, and it survives the excess being a guess.'),
  ('cementing', 'beginner', 'module', 'm05-sacks-time-and-the-sheet', 15, 'In one sentence, what does the Associate tier of this course claim?', '["That a well-ordered cement job will isolate the reservoir.", "That the volume sheet is cylinder arithmetic on lengths and diameters, and only one of its inputs is a guess.", "That the top of cement can be predicted to within thirty metres provided the open hole excess is chosen from offset data.", "That the displacement volume is the largest number on the sheet and therefore the one most worth getting right."]'::jsonb, 1, 'And the answer is linear in the guess.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Summarising the Associate tier: what kind of calculation is a volume sheet?', '["A fluid mechanics calculation on the flow path.", "Cylinder arithmetic on lengths and diameters, with exactly one input that nobody measured.", "A statistical estimate, since the open hole excess carries a distribution and every volume on the sheet inherits it.", "A geometric calculation that also depends on the trajectory, because a deviated hole holds more cement per vertical metre."]'::jsonb, 1, 'Every other input is a published table, a joint tally, a bit stamp, a laboratory test or a design decision.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 2, 'A capstone asks for volumes on a casing size the lessons never used. What has to change?', '["The annular capacities only, since the bore is unchanged.", "The excess convention, since a larger casing in a larger hole carries a different washout allowance in the published tables.", "Every capacity, and also the shoe track convention, because a larger string uses a proportionally longer float shoe joint.", "Every capacity, both the annular one and the inside one, and nothing about the method."]'::jsonb, 3, 'The procedure does not depend on the numbers it is given.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Working a volume capstone, which field should you compute first?', '["The effective bore after the excess, because every volume below the previous shoe depends on it.", "The displacement, because it is the largest.", "The total slurry, since the annular slurry and the shoe track are both derived from it by subtraction once it is known.", "The sacks, because the yield fixes the relationship between the slurry volume and everything else on the sheet."]'::jsonb, 0, 'Inflate the capacity by the excess, then back-solve the bore. Never inflate the diameter.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 4, 'A displacement volume comes out too large by exactly the shoe track. What was done?', '["The excess was applied to the inside capacity.", "The casing inside diameter was taken from the wrong row of the table, giving a bore too large by about a millimetre.", "It was measured to the shoe rather than to the float collar.", "The top of cement was used as the upper endpoint rather than surface, which adds the volume above it to the total."]'::jsonb, 2, 'The two volumes are exactly the inside capacity times the two depths, and their difference is the track.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 5, 'An effective bore comes out at 0.33 rather than 0.32. What is the likely cause?', '["The wrong casing outside diameter was used.", "The excess was applied to the diameter rather than to the area, which overstates the bore.", "The cased row''s bore was used rather than the open hole one, since the two are close together on this hole programme.", "The excess was applied twice, once in the capacity and once again when the bore was back-solved from the capacity."]'::jsonb, 1, 'A ten percent bigger diameter is a twenty one percent bigger area, and the excess is quoted as a volume excess.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 6, 'Which free check catches a slurry volume computed on the wrong capacity?', '["The annular slurry plus the shoe track must equal the total slurry, exactly.", "The sacks times the yield must equal the total slurry.", "The displacement divided by the inside capacity must equal the float collar depth, which checks the inside side of the sheet.", "The lead plus the tail must equal the total slurry, which holds by construction whatever the split depth happens to be."]'::jsonb, 0, 'The lead plus tail check holds by construction and therefore catches nothing.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 7, 'You suspect the casing bore was mistyped. What is the fastest way to find out?', '["Comparing it against the slurry volume.", "Adding it to the shoe track and dividing by the shoe depth, which returns the inside capacity if both were computed correctly.", "Dividing it by the inside capacity, which must return the float collar depth, and which also checks the capacity at the same time.", "Dividing it by the inside capacity must return the float collar depth exactly."]'::jsonb, 3, 'It is the fastest way to check two fields at once.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 8, 'A capstone job has 100 m of cased annulus and 1050 m of open hole above the shoe. What follows?', '["The excess applies to the whole 1150 m.", "The lead and tail split has to be placed at the previous shoe, because the engine cuts an annulus row there and nowhere else.", "The annular slurry spans two capacities and only the open hole part responds to the excess.", "The annular slurry is 1150 m times the open hole capacity, since the cased section above the shoe is inside the previous string."]'::jsonb, 2, 'Which is the same structure as the lessons'' job, on different numbers.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 9, 'How do you check that a capstone effective bore is plausible without recomputing it?', '["It must be exactly 30 percent above the bit size.", "It must lie between the bit size and the bore of the casing the string was run through.", "It must equal the bit size times the square root of one plus the excess, which is the definition of the effective bore.", "It must be smaller than the bit size, because the excess describes the volume rather than the diameter of the hole."]'::jsonb, 1, 'Outside that range and the excess was applied to the wrong quantity.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 10, 'What is the size check on a bigger casing in a bigger hole over a shorter interval?', '["Expect a larger annular slurry despite the shorter interval, because the annulus is much bigger.", "Expect a smaller slurry, since the interval is shorter.", "Expect the same slurry, since the annular capacity and the interval length trade off against each other in the calculation.", "Expect a smaller displacement, since the shorter string holds less fluid inside it than the deeper one the lessons cement."]'::jsonb, 0, 'A 12-1/4 inch hole around 9-5/8 inch casing at 30 percent excess is a much bigger annulus than 8-1/2 around 7 at 15.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 11, 'What does an Associate in this course claim to be able to produce?', '["A cement programme that will isolate the reservoir.", "A prediction of the achieved top of cement to within thirty metres, given a caliper log over the open hole section.", "A volume sheet and the placement pressures that follow from it, which together are the two halves of a cement design.", "A defensible purchase order and pumping schedule for a full casing string in any hole geometry."]'::jsonb, 3, 'Whether the job will work is the next two tiers and three things outside the course.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 12, 'What is the first question the Professional tier answers that this one cannot?', '["How much cement to order for a given top of cement.", "Whether the casing is centred well enough for the cement to displace the mud from the narrow side of the annulus.", "Where every fluid is at every moment, and what pressure that takes.", "Whether the slurry will still be pumpable when it reaches the annulus, which needs a thickening time and a temperature."]'::jsonb, 2, 'The volume sheet cannot tell a slant well from a horizontal one, and the placement can.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Which later course places the load this course''s cement column applies?', '["Well Integrity and P and A, decades later.", "Casing and Tubing Design, whose cementing collapse case is water inside the pipe and wet cement outside.", "Drilling Fluids and Hydraulics, which owns the loss kernel the placement simulation imports for its friction term.", "Geomechanics, which supplies the fracture gradient the equivalent circulating density is compared against during the job."]'::jsonb, 1, 'The two courses meet at the same annulus from opposite sides.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 14, 'What single habit should you carry out of this tier?', '["Write the excess next to the volume, because the answer is linear in it and it is the only guess on the sheet.", "Always order fifteen percent excess.", "Compute every volume twice, once to the shoe and once to the float collar, so that the shoe track is never lost by accident.", "Report the slurry volume to three significant figures, since the precision beyond that is an artefact of the arithmetic."]'::jsonb, 0, 'A slurry volume with no excess figure attached is not a result.'),
  ('cementing', 'beginner', 'module', 'm06-the-associate-reading', 15, 'Which two of the four job requirements does this tier NOT compute?', '["Ordering the right volumes, and not breaking the hole.", "Removing the mud, and keeping the slurry pumpable, which are the two the Expert tier and the laboratory each cover in turn.", "Getting the cement where it was meant to go, and removing the mud.", "Not breaking the hole, and removing the mud, which are the Professional and Expert tiers of this course respectively."]'::jsonb, 2, 'It orders the volumes, and the other three are elsewhere.'),
  ('cementing', 'beginner', 'final', null, 1, 'A cement sheath is described as a barrier. What is the other half of the barrier?', '["The wellhead and the pressure control equipment.", "The casing itself, which is a pipe with a hole around it until the annulus is filled.", "The float equipment, which holds the cement in the annulus while it sets and prevents it U-tubing back into the casing.", "The formation, which provides the outer boundary and which the cement bonds to across the whole of the open hole."]'::jsonb, 1, 'Steel alone leaves an open channel from the reservoir to surface.'),
  ('cementing', 'beginner', 'final', null, 2, 'A well produces water it should not after eight years. Which cement failure fits?', '["A mud channel on the narrow side of an eccentric annulus, left because the casing was not centred.", "An under-displaced job that set inside the casing.", "A slurry that never reached the target top of cement, which would have been visible as a short volume during the job.", "A pressure test failure at the shoe, which would have been found before the next hole section was drilled ahead."]'::jsonb, 0, 'It does not announce itself during the job and it shows up decades later.'),
  ('cementing', 'beginner', 'final', null, 3, 'Which two of the four job requirements pull the pump rate in opposite directions?', '["Ordering the right volumes and getting them to the top.", "Getting the cement where it was meant to go and not breaking the hole, since a higher top of cement raises the density.", "Not fracturing the shoe above, which wants a low rate, and removing the mud, which wants a high annular velocity.", "Not breaking the hole, which wants it slow, and removing the mud, which wants it fast."]'::jsonb, 3, 'Free fall adds a third pull, and it wants the rate high as well.'),
  ('cementing', 'beginner', 'final', null, 4, 'Which single number distinguishes the shoe track from the displacement?', '["The top of cement, which is where the plug lands.", "The excess factor, which applies to the shoe track because it is in open hole and not to the displacement inside the casing.", "The float collar depth, since the displacement runs to it and the shoe track runs from it to the shoe.", "The casing inside diameter, since the shoe track uses the drift diameter and the displacement uses the nominal bore."]'::jsonb, 2, 'Both are the inside capacity times a length, and the two lengths add to the shoe depth.'),
  ('cementing', 'beginner', 'final', null, 5, 'This course''s casing is 0.1778 m outside and 0.1570736 m inside. What is the inside capacity?', '["About 0.0134 square metres, the annular value.", "About 0.0194 square metres, which is pi over four times the square of the inside diameter.", "About 0.0248 square metres, which is pi over four times the square of the outside diameter of the string being cemented.", "About 0.0054 square metres, which is the steel cross-section and is what the buoyed weight of the string is computed from."]'::jsonb, 1, 'The annular capacities are 0.013356688045922537 cased and 0.011780948889016823 at the bit size.'),
  ('cementing', 'beginner', 'final', null, 6, 'Which four depths get a row edge, and which two do not?', '["At the section boundaries and the shoe, and not at the top of cement or the lead and tail split.", "At every depth where the annular capacity changes.", "At the section boundaries, the shoe, the top of cement and the split, so that every volume endpoint falls on a row edge.", "At each survey station, so that the true vertical depth of each row end is available without interpolation later on."]'::jsonb, 0, 'The top of cement and the split are handled by overlapping with the rows rather than by cutting them.'),
  ('cementing', 'beginner', 'final', null, 7, 'A hole description covers 0 to 500 m and 800 to 3000. What does the engine do?', '["Fills the gap with the section above it.", "Interpolates the bore across the gap between the two sections, which is what a real hole would do if it were not logged.", "Throws, naming the interval it could not cover.", "Warns and continues with a volume computed over the covered intervals only, which is smaller than the true annular volume."]'::jsonb, 2, 'A volume calculated over a gap would silently be too small.'),
  ('cementing', 'beginner', 'final', null, 8, 'The excess factor multiplies which quantity?', '["The diameter of the open hole rows.", "The capacity of open hole rows, and nothing else in the whole calculation.", "The annular volume between the top of cement and the shoe, including the part of it inside the previous casing string.", "The total slurry volume, since the whole of it is affected by the hole being larger than the bit that drilled it."]'::jsonb, 1, 'Cased rows and everything inside the casing are untouched.'),
  ('cementing', 'beginner', 'final', null, 9, 'Why is the effective bore back-solved rather than assumed?', '["So the same annulus does not have one area for the volume and a different one for the friction calculation.", "Because the diameter is what the excess is quoted against.", "Because the placement simulation needs a capacity and the volume sheet needs a diameter, and the two must be consistent.", "Because the back-solve is exact and inflating the diameter directly would introduce a rounding error in the fourth digit."]'::jsonb, 0, 'The friction kernel takes a characteristic dimension and the annular one is the bore less the casing outside diameter.'),
  ('cementing', 'beginner', 'final', null, 10, 'At 15 percent excess this well''s open hole reads 0.22104932820526735 m against a cased bore of 0.2204974. What follows?', '["Nothing, since the two are within a millimetre.", "The open hole annular velocity is higher than the cased one, which improves mud removal in the section that needs it most.", "The open hole annulus becomes the wider of the two, which makes it the SLOWEST annulus and therefore the worst for mud removal.", "The washed-out open hole annulus is wider than the cased one above it, which at the bit size it was not."]'::jsonb, 3, 'The annular velocity is lowest where the annulus is widest.'),
  ('cementing', 'beginner', 'final', null, 11, 'The slurry volume is linear in the excess. What does that let you do?', '["Interpolate between published excess tables.", "Solve for the excess that would have been needed, once a caliper log has established the true volume of the open hole section.", "Run two cases and read the whole sensitivity line off them.", "Report a single number without qualification, since a linear relationship carries no uncertainty of its own into the answer."]'::jsonb, 2, 'Two runs give the line, and a reader can see the sensitivity at a glance.'),
  ('cementing', 'beginner', 'final', null, 12, 'Which volumes on the sheet are unaffected by the excess?', '["Only the displacement, since the rest is annular.", "The displacement, the shoe track, and the part of the annular slurry inside the previous casing.", "None of them, since the excess is applied when the annulus rows are built and every volume on the sheet reads those rows.", "The lead volume, since a lead slurry is always placed inside the previous casing rather than across the open hole section."]'::jsonb, 1, 'On this well about eleven percent of the annular slurry is inside the previous casing.'),
  ('cementing', 'beginner', 'final', null, 13, 'Why is the cement brought up inside the previous casing rather than stopped at its shoe?', '["The lap, so the overlap between the two casing strings is cemented rather than relying on the shoe track above.", "The regulatory minimum above the reservoir.", "The length of lead slurry the volume sheet needs in order to have a distinct lead and tail split at a row boundary.", "The distance the cement is expected to fall short by, allowed for in the design so that the target is still reached."]'::jsonb, 0, 'It is also exactly the lead volume on both wells, because the split is at the previous shoe.'),
  ('cementing', 'beginner', 'final', null, 14, 'How many places in the volume sheet read the target cement top?', '["In the displacement, as a lower limit.", "In two places, the annular slurry and the lead volume, since the lead runs from the top of cement down to the split depth.", "Once, as the upper end of the volume between it and the shoe, and nothing else about the top of cement matters to the sheet.", "As the shallow endpoint of the annular integral, once."]'::jsonb, 3, 'The engine refuses a negative one and one below the shoe, and imposes nothing else.'),
  ('cementing', 'beginner', 'final', null, 15, 'The two wells have the same annular slurry volume. What would break that?', '["A different total depth or a different trajectory.", "A different length of open hole or of cased annulus above the shoe, in either well.", "A different top of cement, since the volume between it and the shoe is what the annular slurry is and the two tops differ.", "A different pump rate, since the annular slurry is quoted at the rate the job is pumped at and the two wells differ there."]'::jsonb, 1, 'Both have 200 m of cased annulus and 1600 m of open hole, and every other difference is invisible to the sheet.'),
  ('cementing', 'beginner', 'final', null, 16, 'What is the shoe track''s purpose in one sentence?', '["Giving the top plug somewhere to land.", "Providing a reserve of cement in case the annulus takes more than the sheet predicted, which is the commonest volume error.", "Keeping the most contaminated cement inside the casing rather than at the shoe.", "Holding the weight of the annular column so that the float equipment is not the only thing preventing a reverse U-tube."]'::jsonb, 2, 'The shoe is where the next leak-off test is performed and where the cement most needs to be good.'),
  ('cementing', 'beginner', 'final', null, 17, 'You move the split 300 m deeper. What happens to the ordered slurry?', '["Nothing at all. It moves volume between two columns of the sheet and changes no total.", "It increases the total if moved deeper.", "It changes the sacks, because the lead and the tail have different yields and the split decides how much of each is needed.", "It changes the achieved top of cement, since the two slurries have different densities and therefore different U-tube behaviour."]'::jsonb, 0, 'It changes the placement completely and the volume not at all.'),
  ('cementing', 'beginner', 'final', null, 18, 'Which product of a capacity and a depth gives 57.357205971317775 cubic metres?', '["The inside capacity times the shoe depth of 3000 m.", "The total pumped volume less the slurry and the spacer, which is how the engine derives it from the other three volumes.", "The inside capacity times the float collar depth, which is the volume the top plug has to travel through to reach its seat.", "The inside capacity times the float collar depth of 2960 m."]'::jsonb, 3, 'The inside capacity times the shoe depth is 58.13230334930856, which is that plus the shoe track.'),
  ('cementing', 'beginner', 'final', null, 19, 'A slurry yield of 0.0382 cubic metres a sack gives 657.6801293970221 sacks. Of what?', '["The annular slurry only, excluding the shoe track.", "The total slurry volume of 25.123380942966243 cubic metres, including the shoe track.", "The total pumped volume of 86.48058691428402, since the displacement fluid is also mixed at the cement unit on most rigs.", "The tail volume of 22.452043333781734, since the lead has a different yield and is counted separately from it."]'::jsonb, 1, 'The engine divides the whole slurry by one yield, which is approximate on a two-slurry job.'),
  ('cementing', 'beginner', 'final', null, 20, 'What does the engine report if no pump rate is given?', '["A job time at a default rate of 0.02 cubic metres a second.", "An error, because the placement simulation cannot be run without a rate and the volume routine calls into it for the timing.", "A job time computed from the mixing rate instead, which is the constraint on a continuously mixed job in any case.", "No job time, and every other volume as usual."]'::jsonb, 3, 'Same discipline as the sacks: no input, no invented default.'),
  ('cementing', 'beginner', 'final', null, 21, 'The reported job time is 4324.029345714201 seconds and the real one is commonly longer. Why?', '["Because the rate falls as the cement gets heavier.", "Because the engine computes the time from the slurry volume alone, and the displacement takes longer than the cement does.", "Mixing, rate changes, the plug drop and the changeover are all outside a total-over-rate calculation.", "Because the pump efficiency is below one, and the calculated rate is the theoretical output rather than the delivered one."]'::jsonb, 2, 'Real jobs slow down to displace the plugs and slow down again for the bump.'),
  ('cementing', 'beginner', 'final', null, 22, 'Two wells with the same slurry volume have displacements differing by 3.875486889953905 cubic metres. Why?', '["Their annular capacities differ by that amount.", "One well is horizontal, so its displacement is measured along the hole while the other''s is measured vertically downward.", "Their float collars are at different depths, and the difference is that depth difference times the casing bore capacity.", "Their float collars are 200 m apart, and that times the inside capacity is exactly the difference."]'::jsonb, 3, 'It is the first volume in the whole sheet that distinguishes the two wells.'),
  ('cementing', 'beginner', 'final', null, 23, 'What does it mean that the volume sheet reads only measured depths?', '["The survey is not needed to produce a volume sheet.", "A 1600 m horizontal lateral holds exactly as much cement as 1600 m of vertical hole of the same size.", "The true vertical depth has to be computed separately for the placement, since the hydrostatic head depends on it directly.", "A deviated well needs more cement than a vertical one to the same true vertical depth, in proportion to the hole length."]'::jsonb, 1, 'The engine does report the true vertical depths at the shoe and the top of cement, and does not use them for volume.'),
  ('cementing', 'beginner', 'final', null, 24, 'Which is the most defensible number on a volume sheet?', '["The casing dimensions, from a published API table to four decimals.", "The open hole excess, from offset well experience.", "The slurry yield, which is measured in a laboratory on the actual blend at the actual conditions the job will be pumped at.", "The top of cement, since it is chosen by an engineer who can defend it against a regulation and a lap requirement."]'::jsonb, 0, 'The excess is the only guess, and it is in the first significant figure while every other uncertainty is in the third.'),
  ('cementing', 'beginner', 'final', null, 25, 'Six things a volume sheet hides. Which does the Expert tier of this course address?', '["Whether the cement will be pumpable when it arrives.", "Whether the hole will take the cement, which is the equivalent circulating density at the shallowest exposed formation.", "Whether the mud will get out of the way, through the standoff calculation.", "Whether the top of cement will actually be reached, which the placement simulation reports and warns about directly."]'::jsonb, 2, 'Pumpability and contamination are outside the course entirely.'),
  ('cementing', 'beginner', 'final', null, 26, 'A cement job''s biggest lever on mud removal is not in this engine. Which is it?', '["The centralizer spacing, which the Expert tier computes.", "The spacer volume, since the spacer is what separates the mud from the cement and keeps the two from flocculating on contact.", "The pump rate, since the annular velocity is what scours the mud off the wall and the rate is what sets the velocity.", "Rotating or reciprocating the casing during the job."]'::jsonb, 3, 'It is more effective than centralization on many wells and nothing here represents it.'),
  ('cementing', 'beginner', 'final', null, 27, 'What does the engine''s version string on every result let you do?', '["Trace a saved answer back to the code that produced it.", "Verify the inputs it was computed from.", "Compare two results from different runs and know whether any difference between them came from the inputs or the engine.", "Reproduce the answer exactly, since the version fixes both the algorithm and the floating point behaviour of the platform."]'::jsonb, 0, 'A placement result and a standoff profile both carry it.'),
  ('cementing', 'beginner', 'final', null, 28, 'A liner job is refused. What would have gone wrong if the engine had guessed?', '["Only the displacement volume would be wrong.", "Nothing, since a liner is geometrically a full string that starts at the hanger rather than at surface and the maths is the same.", "The annulus rows would start at the hanger, and every volume above it would be understated by the length of the work string.", "The flow path, the displacement volume and the U-tube are all different, and every number would be plausibly wrong."]'::jsonb, 3, 'The engine names which phase the input belongs to rather than approximating.'),
  ('cementing', 'beginner', 'final', null, 29, 'Which of the six refusals would produce the hardest error to spot in a finished sheet?', '["A liner job, which would give an absurd displacement.", "A casing that does not fit the hole, which would give a negative annular capacity and therefore a negative slurry volume.", "A hole description with a gap, because the resulting volume is merely a bit too small.", "A float collar below the shoe, which would give a negative shoe track and a displacement larger than the whole casing bore."]'::jsonb, 2, 'The other five produce numbers that are obviously wrong; a gap produces a number that is quietly wrong.'),
  ('cementing', 'beginner', 'final', null, 30, 'You are handed a volume sheet with no excess figure on it. What do you do?', '["Assume 15 percent, which is the industry default.", "Send it back, because the answer is linear in the missing number and cannot be interpreted without it.", "Recompute the slurry at zero excess and use the difference to infer what excess was assumed when the sheet was produced.", "Accept it, since the excess only affects the open hole part and the top of cement is what the sheet is really for."]'::jsonb, 1, 'It is a result whose first significant figure depends on the number that was left off.'),
  ('cementing', 'beginner', 'final', null, 31, 'The slant well''s open hole annular volume is 18.849518222426916 cubic metres at the bit size. At 15 percent excess?', '["21.676945955790952, which is fifteen percent more, because the excess multiplies the capacity directly.", "19.5, since the excess applies to the diameter.", "21.676945955790952, which is fifteen percent more in area and about seven percent more in the effective bore diameter.", "24.34828356497546, which is the annular slurry including the 200 m of cased annulus above the previous shoe."]'::jsonb, 0, 'And the annular slurry becomes 24.34828356497546 once the cased part is added.'),
  ('cementing', 'beginner', 'final', null, 32, 'What is the relationship between the total inside volume and the two inside volumes on the sheet?', '["Inside capacity times shoe depth equals displacement.", "Inside capacity times float collar depth equals the displacement plus the shoe track, which is why the two are quoted apart.", "Inside capacity times shoe depth equals the displacement plus the shoe track, which on this well is 58.13230334930856.", "Inside capacity times shoe depth equals displacement plus shoe track."]'::jsonb, 3, 'On the slant well that is 57.357205971317775 plus 0.7750973779907808.'),
  ('cementing', 'beginner', 'final', null, 33, 'Why does the engine report the true vertical depth at the shoe and at the top of cement?', '["Because the annular capacity depends on the inclination.", "Because the placement needs them for the hydrostatic head, even though the volume calculation does not.", "Because a regulatory filing requires the top of cement to be quoted in true vertical depth rather than in measured depth.", "Because the excess factor is applied per vertical metre, so the two depths are needed to convert the annular volumes."]'::jsonb, 1, 'On the slant well they are 2507.9196993011733 and 1129.0397016870152.'),
  ('cementing', 'beginner', 'final', null, 34, 'A job is pumped and the plug does not bump at the calculated displacement. What has that told you?', '["Something in the inside geometry or the displacement arithmetic was wrong.", "That the annulus took more cement than expected.", "That the open hole excess was underestimated, since the extra volume the hole swallowed has to come from somewhere.", "That the top of cement is short of its target, which a temperature log after the job would confirm independently."]'::jsonb, 0, 'It confirms the inside geometry and says nothing at all about the annulus.'),
  ('cementing', 'beginner', 'final', null, 35, 'Which volume dominates the job time, and why?', '["The slurry, because it is mixed as well as pumped.", "The spacer, because it is pumped at a reduced rate to avoid contaminating the cement behind it at the interface.", "The displacement, at 57.357205971317775 against 25.123380942966243 of slurry, so about two thirds of the pumping time.", "The displacement, because it is more than twice the slurry and the rate is the same for both."]'::jsonb, 3, 'Which is also why an excess change barely moves the job time.'),
  ('cementing', 'beginner', 'final', null, 36, 'In the elastic sense, what is the excess factor most like in the other courses of this module?', '["A design factor applied to a published rating.", "A first-significant-figure uncertainty on an input that every downstream answer is linear in.", "A published empirical fit, like the collapse coefficients, whose scatter is inherited by everything computed from it.", "A discretisation parameter, like the number of steps in the placement, whose effect can be tested by refining it."]'::jsonb, 1, 'Every other uncertainty on the sheet is in the third or fourth figure.'),
  ('cementing', 'beginner', 'final', null, 37, 'Somebody holding this tier''s certificate has been signed off for what?', '["That the holder can design a cement job end to end.", "That the holder can predict whether a cement job will isolate the reservoir, given the geometry and the fluid programme.", "That the holder can produce a defensible volume sheet for a full casing string in any hole geometry.", "That the holder can compute the placement pressures and the standoff, which together decide whether the job will work."]'::jsonb, 2, 'The volume sheet is the ordering document, and it is a necessary condition rather than close to a sufficient one.'),
  ('cementing', 'beginner', 'final', null, 38, 'The two errors on the excess are asymmetric. Which is worse and how much worse?', '["Guessing low, because it leaves uncemented annulus, and 15 points low is about 212 m of it on this well.", "Guessing high, because the cement is expensive.", "Guessing high, because a taller annular column raises the circulating density and can fracture the shallowest exposed shoe.", "Neither, because the placement simulation would warn about the achieved top of cement in either direction of error."]'::jsonb, 0, 'Guessing high mostly costs money and margin, and guessing low costs isolation.'),
  ('cementing', 'beginner', 'final', null, 39, 'Which of the four job requirements does the volume sheet actually address?', '["Getting the cement where it was meant to go.", "Not breaking the hole, since the volume determines the height of the annular column and therefore the pressure it exerts.", "Ordering the volumes, which is the first of four, and the other three belong to the two tiers above and to the laboratory.", "Ordering the right volumes, which is the first of the four."]'::jsonb, 3, 'The other three are placement, standoff and chemistry.'),
  ('cementing', 'beginner', 'final', null, 40, 'What is the general lesson from the excess module?', '["Always use a generous excess figure.", "An answer whose precision exceeds the precision of its worst input is quoting arithmetic rather than engineering.", "Any input that nobody measured should be swept rather than assumed, so that the reader can see the range of the answer.", "The open hole is always bigger than the bit, so a volume computed at the bit size is always an underestimate."]'::jsonb, 1, 'It is the same habit the Casing and Tubing course taught as computing the gap.'),
  ('cementing', 'beginner', 'final', null, 41, 'A capstone gives a 9-5/8 inch casing in a 12-1/4 inch hole at 30 percent excess. What is different from the lessons?', '["Both capacities, the excess and the interval lengths, and nothing about the method.", "Only the annular capacity, since the casing is the same.", "The excess convention, since a hole that large is quoted at a volume excess rather than the diameter excess used for smaller ones.", "The shoe track convention, since a larger casing uses a longer float shoe joint and therefore a proportionally longer track."]'::jsonb, 0, 'The procedure does not depend on the numbers it is given.'),
  ('cementing', 'beginner', 'final', null, 42, 'You compute an annular slurry that is smaller than the same interval at zero excess. What happened?', '["Nothing, since the excess reduces the annular capacity.", "The cased row was inflated and the open hole row was not, which is the reverse of what the engine does with the excess.", "The excess was applied as a divisor rather than a multiplier, or to the wrong row.", "The top of cement was taken below the previous shoe, which removes the cased contribution from the annular slurry entirely."]'::jsonb, 2, 'The excess can only increase a volume, so a smaller answer is an input error and not a result.');
